/*{
  "DESCRIPTION": "A calm base colour with a bright accent flashing across it every couple of seconds",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 0.2, 0.9, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.05, "MAX": 0.4, "DEFAULT": 0.15 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // 100 * 0.5 is whole: one flash every two seconds at speed 1, wrapping cleanly.
  float t = mod(TIME * speed, 100.0) * 0.5;
  float d = isLine ? uv.x : (uv.x * aspect + uv.y) / (aspect + 1.0);
  // The accent is a soft bar that crosses the whole display in the first half of each cycle
  // and is gone for the second half - the calm is the point.
  float phase = fract(t);
  float pos = phase * 2.4 - 0.7;
  float bar = smoothstep(width, 0.0, abs(d - pos)) * step(phase, 0.5);
  // The base breathes very slightly, so the calm is alive rather than a still image.
  float breathe = 0.8 + 0.2 * sin(mod(TIME * speed, 62.831853) * 0.5 + d * 2.0);
  vec3 col = colorA.rgb * breathe;
  col = mix(col, colorB.rgb, bar);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Curtains of aurora rippling slowly across the sky, bright at the base",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 1.0, 0.4, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.6, 0.1, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "folds", "TYPE": "float", "MIN": 1.0, "MAX": 8.0, "DEFAULT": 4.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float t = mod(TIME * speed, 62.831853);
  float x = uv.x * folds;
  // The folds of the curtain: a slow large wave with a faster ripple over it. Whole tenths for
  // every frequency, so the twenty-pi wrap is seamless.
  float fold = 0.5 + 0.5 * sin(x * 1.9 + t * 0.7 + sin(x * 0.7 - t * 0.4) * 2.0);
  fold = fold * 0.65 + 0.35 * (0.5 + 0.5 * sin(x * 4.3 - t * 1.1));
  float y = isLine ? 0.3 : uv.y;
  // Brightest at the base, thinning towards the top of the sky.
  float base = 1.0 - smoothstep(0.0, 1.1, y);
  float lum = clamp(fold * 1.3 * (0.35 + base), 0.0, 1.0);
  // Green at the foot, violet higher up - two flat zones with a narrow edge, not a gradient.
  vec3 col = mix(colorA.rgb, colorB.rgb, smoothstep(0.42, 0.62, y + 0.15 * fold));
  gl_FragColor = vec4(col * (0.3 + 0.7 * lum), 1.0);
}

/*{
  "DESCRIPTION": "A barber pole of bold red and white diagonals turning steadily",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.05, 0.05, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "stripes", "TYPE": "float", "MIN": 2.0, "MAX": 10.0, "DEFAULT": 4.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // 100 * 0.5 is whole, so the turn never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0);
  // A pole is a cylinder seen from the side: the stripes are steep diagonals that travel
  // upward, and the shading across x is what makes it round rather than flat.
  float d = isLine ? uv.x : uv.x * min(aspect, 2.0) * 0.5 + uv.y;
  float v = fract(d * stripes - t * 0.5);
  float s = abs(v - 0.5) * 2.0;
  float aa = 2.0 * stripes / max(RENDERSIZE.x, 8.0);
  float band = smoothstep(0.5 + aa, 0.5 - aa, s);
  vec3 col = mix(colorB.rgb, colorA.rgb, band);
  // Rounder: brighter down the middle of the pole, darker at its edges. Never below 0.6.
  float round = isLine ? 1.0 : 0.6 + 0.4 * sin(uv.x * 3.14159);
  gl_FragColor = vec4(col * round, 1.0);
}

/*{
  "DESCRIPTION": "Red and white candy cane stripes spiralling steadily along the display",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.05, 0.05, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "stripes", "TYPE": "float", "MIN": 2.0, "MAX": 12.0, "DEFAULT": 5.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // Wrapped so the scroll never loses precision; 100 * 0.5 is whole, so the wrap is seamless.
  float t = mod(TIME * speed, 100.0);
  // Diagonal on a matrix, straight along a line: the stripe still travels the same way.
  float d = isLine ? uv.x : (uv.x * aspect + uv.y) / (aspect + 1.0);
  float v = fract(d * stripes - t * 0.5);
  // 0 in the middle of a stripe, 1 at its edges; a pixel and a half of softening so neighbouring
  // bulbs on a roofline never sit at opposite brightness.
  float s = abs(v - 0.5) * 2.0;
  float aa = 1.5 * stripes / max(RENDERSIZE.x, 8.0);
  float band = smoothstep(0.5 + aa, 0.5 - aa, s);
  gl_FragColor = vec4(mix(colorB.rgb, colorA.rgb, band), 1.0);
}

/*{
  "DESCRIPTION": "The bright wobbling caustics you see on the bottom of a swimming pool",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 0.55, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.85, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 1.0, "MAX": 5.0, "DEFAULT": 2.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(min(aspect, 3.0), 1.0) * scale;
  if (isLine) p.y = 0.4 * sin(p.x * 1.3);
  float t = mod(TIME * speed, 62.831853);
  // Two wobbling sine lattices; a caustic is where their bright lines cross. Whole tenths, so
  // the twenty-pi wrap is seamless.
  vec2 q = p + vec2(sin(p.y * 1.7 + t * 0.9), cos(p.x * 1.5 - t * 0.7)) * 0.4;
  float l1 = abs(sin(q.x * 2.1 + t * 0.5));
  float l2 = abs(sin(q.y * 2.3 - t * 0.6));
  float l3 = abs(sin((q.x + q.y) * 1.6 + t * 0.4));
  float net = pow(l1 * l2, 0.5) * 0.6 + pow(l2 * l3, 0.5) * 0.4;
  // The water is bright blue all over; the caustic lines flash white where the net is thin.
  float line = smoothstep(0.55, 0.15, net);
  vec3 col = colorA.rgb * (0.55 + 0.45 * (1.0 - net));
  col = mix(col, colorB.rgb, line * 0.9);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Champagne gold shimmering and rising like bubbles in a glass",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.45, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "bubbles", "TYPE": "float", "MIN": 0.2, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/
float hash(vec2 c) {
  return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  // Bubbles rise; on a line they drift along it. Swap the axes and the same code runs.
  vec2 size = isLine ? RENDERSIZE.yx : RENDERSIZE;
  vec2 px = (isLine ? uv.yx : uv) * size;
  // 100 * 0.1 is whole, so every rise rate below wraps seamlessly.
  float t = mod(TIME * speed, 100.0);
  float scale = max(1.0, min(size.x, size.y) / 32.0);
  float colW = 3.0 * scale;
  float cols = max(1.0, floor(size.x / colW));
  float bubble = 0.0;
  for (int layer = 0; layer < 2; layer++) {
    float fl = float(layer);
    float c = floor(px.x / (size.x / cols));
    float h = hash(vec2(c, fl));
    if (h > bubbles) continue;
    float rate = 0.1 + 0.1 * floor(hash(vec2(c + 5.0, fl)) * 3.0);
    // Rising: y increases with time, and wobbles a little on the way up.
    float fy = fract(h * 3.0 + fl * 0.5 + t * rate);
    float cx = (c + 0.5) * (size.x / cols) + sin(fy * 12.566 + h * 6.28) * 0.7 * scale;
    float d = length(px - vec2(cx, fy * size.y));
    bubble = max(bubble, smoothstep(1.4 * scale, 0.3 * scale, d));
  }
  // The glass itself glows: a warm base with a slow shimmer running through it.
  float shimmer = 0.55 + 0.15 * sin(px.y * 0.4 / scale - mod(TIME * speed, 62.831853) * 1.1) * sin(px.x * 0.3 / scale + 1.0);
  float lit = shimmer + (1.0 - shimmer) * bubble;
  gl_FragColor = vec4(colorA.rgb * lit, 1.0);
}

/*{
  "DESCRIPTION": "Big bold checkerboard squares sliding steadily sideways",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.1, 0.8, 0.2, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "squares", "TYPE": "float", "MIN": 2.0, "MAX": 8.0, "DEFAULT": 4.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // 100 * 0.5 is whole, so the slide never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0);
  // Square squares: the count runs across the width, and the height gets as many as fit.
  float cx = uv.x * squares + t * 0.5;
  float cy = uv.y * squares / max(aspect, 0.25);
  float parity = mod(floor(cx) + floor(cy), 2.0);
  // A one-pixel dark seam between squares, so the board reads as squares and never blends two
  // palette colours through a muddy edge.
  float aaX = 1.2 * squares / max(RENDERSIZE.x, 8.0);
  float aaY = 1.2 * squares / max(aspect, 0.25) / max(RENDERSIZE.y, 8.0);
  float fx = fract(cx);
  float fy = fract(cy);
  float seam = smoothstep(0.0, aaX, fx) * smoothstep(1.0, 1.0 - aaX, fx) * smoothstep(0.0, aaY, fy) * smoothstep(1.0, 1.0 - aaY, fy);
  // On a line the seams would be dark bulbs between bright ones, so there the squares just butt.
  if (RENDERSIZE.y < 2.0) seam = 1.0;
  vec3 col = mix(colorA.rgb, colorB.rgb, parity);
  gl_FragColor = vec4(col * (0.15 + 0.85 * seam), 1.0);
}

/*{
  "DESCRIPTION": "Soft clouds drifting slowly across a coloured sky, always well lit",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.2, 0.55, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "cover", "TYPE": "float", "MIN": 0.2, "MAX": 0.8, "DEFAULT": 0.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  float t = mod(TIME * speed, 62.831853);
  // Clouds drift left to right. Three octaves of sines, all whole tenths, so the wrap is seamless.
  float x = uv.x * min(aspect, 3.0) * 3.0 - t * 0.3;
  float y = isLine ? 0.5 : uv.y * 3.0;
  float n = sin(x * 1.1 + sin(y * 1.3) * 1.2) * 0.5;
  n += sin(x * 2.3 + y * 1.7 + t * 0.1) * 0.3;
  n += sin(x * 4.1 - y * 2.9 - t * 0.2) * 0.2;
  n = 0.5 + 0.5 * n;
  // Cloud where the field is high: a soft but definite edge, and a brighter top to each cloud.
  float cloud = smoothstep(1.0 - cover - 0.12, 1.0 - cover + 0.12, n);
  float top = smoothstep(1.0 - cover + 0.15, 1.0 - cover + 0.35, n);
  vec3 col = colorA.rgb * 0.75;
  col = mix(col, colorB.rgb * 0.85, cloud);
  col = mix(col, colorB.rgb, top);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "The whole display washing slowly from one colour to the next, always bright",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.1, 0.9, 0.2, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.1, 0.4, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "sweep", "TYPE": "float", "MIN": 0.0, "MAX": 0.5, "DEFAULT": 0.15 }
  ]
}*/
vec3 pick(float i) {
  if (i < 0.5) return colorA.rgb;
  if (i < 1.5) return colorB.rgb;
  return colorC.rgb;
}
void main() {
  vec2 uv = isf_FragNormCoord;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // 100 * 0.1 is whole, so the cycle never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0);
  // The wash sweeps diagonally across the display rather than switching everywhere at once.
  float d = (uv.x * aspect + uv.y) / (aspect + 1.0);
  float phase = fract(t * 0.1 - d * sweep) * 3.0;
  float idx = floor(phase);
  float next = mod(idx + 1.0, 3.0);
  // Each colour holds for most of its third, then crosses to the next in a short, bright fade
  // rather than a long slide through the muddy midpoint.
  float k = smoothstep(0.8, 1.0, fract(phase));
  vec3 col = mix(pick(idx), pick(next), k);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A bright comet with a long glowing tail chasing itself around the display",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 0.4, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "tailLength", "TYPE": "float", "MIN": 0.2, "MAX": 0.9, "DEFAULT": 0.7 },
    { "NAME": "glow", "TYPE": "float", "MIN": 0.0, "MAX": 0.4, "DEFAULT": 0.22 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  // 20 pi: one orbit per 2 pi seconds at speed 1, and the wrap lands exactly on a whole orbit.
  float t = mod(TIME * speed, 62.831853);

  float back;   // how far behind the head this pixel is, 0..1 around the loop
  float onPath; // 1 on the comet's track, 0 off it
  float head;   // the bright head itself
  if (isLine) {
    float pos = fract(t / 6.2831853);
    back = fract(pos - uv.x);
    onPath = 1.0;
    head = smoothstep(0.06, 0.0, abs(uv.x - pos));
  } else {
    float r = length(p);
    float radius = 0.34 * min(aspect, 1.0);
    float a = atan(p.y, p.x);
    back = fract((t - a) / 6.2831853);
    onPath = smoothstep(0.14, 0.04, abs(r - radius));
    vec2 headPos = vec2(cos(t), sin(t)) * radius;
    head = smoothstep(0.13, 0.0, length(p - headPos));
  }
  // The tail is what moves: it is a function of the head's position, so it reaches the output.
  float tail = pow(clamp(1.0 - back / tailLength, 0.0, 1.0), 2.2) * onPath;
  vec3 col = colorA.rgb * (tail + glow);
  col = mix(col, colorB.rgb, head);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A hard diagonal edge wiping one colour across the display and then the next",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.1, 0.9, 0.2, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.1, 0.4, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/
vec3 pick(float i) {
  if (i < 0.5) return colorA.rgb;
  if (i < 1.5) return colorB.rgb;
  return colorC.rgb;
}
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // 100 * 0.25 is whole, so the wipe never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0) * 0.25;
  // The diagonal: on a line, just the position along it.
  float d = isLine ? uv.x : (uv.x * aspect + uv.y) / (aspect + 1.0);
  // Each wipe crosses the display once per second at speed 1; the colour that has arrived and
  // the one still leaving are the two flat sides of one crisp edge.
  float cycle = floor(t);
  float front = fract(t) * 1.2 - 0.1;
  // Crisp: under a pixel of softening on a matrix, a little more on a line of bulbs.
  float aa = (isLine ? 2.0 : 0.8) / max(RENDERSIZE.x, 8.0);
  float arrived = smoothstep(front + aa, front - aa, d);
  vec3 col = mix(pick(mod(cycle, 3.0)), pick(mod(cycle + 1.0, 3.0)), arrived);
  // A bright hairline on the edge itself, so the wipe reads as a wipe and not a colour change.
  float edge = smoothstep(aa * 3.0, 0.0, abs(d - front));
  col = mix(col, vec3(1.0), edge * 0.6);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Glowing embers rising slowly from a fire and fading as they go up",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.3, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.3, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "embers", "TYPE": "float", "MIN": 0.2, "MAX": 1.0, "DEFAULT": 0.85 }
  ]
}*/
float hash(vec2 c) {
  return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  // Embers rise; on a line they drift along it. Swap the axes and the same code runs.
  vec2 size = isLine ? RENDERSIZE.yx : RENDERSIZE;
  vec2 px = (isLine ? uv.yx : uv) * size;
  float t = mod(TIME * speed, 100.0);
  float scale = max(1.0, min(size.x, size.y) / 32.0);
  float colW = 3.0 * scale;
  float cols = max(1.0, floor(size.x / colW));
  float ember = 0.0;
  float hot = 0.0;
  for (int layer = 0; layer < 2; layer++) {
    float fl = float(layer);
    float c = floor(px.x / (size.x / cols));
    float h = hash(vec2(c, fl));
    if (h > embers) continue;
    float rate = 0.3 + 0.1 * floor(hash(vec2(c + 5.0, fl)) * 3.0);
    // Rising, wandering a little, and dimming with height - an ember goes out as it climbs.
    float fy = fract(h * 3.0 + fl * 0.5 + t * rate);
    float cx = (c + 0.5) * (size.x / cols) + sin(fy * 9.42 + h * 6.28) * 1.2 * scale;
    float d = length(px - vec2(cx, fy * size.y));
    float glow = smoothstep(2.6 * scale, 0.4 * scale, d) * (1.0 - fy * 0.6);
    ember = max(ember, glow);
    hot = max(hot, glow * step(fy, 0.5));
  }
  // The fire at the bottom, where the embers come from: a warm floor that never goes out.
  float floorGlow = isLine ? 0.3 : 0.6 * (1.0 - smoothstep(0.0, 0.22, uv.y)) + 0.1;
  vec3 col = colorA.rgb * max(floorGlow, ember);
  col = mix(col, colorB.rgb, max(hot, ember * 0.5));
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Bright rings expanding outward from the centre one after another",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
