    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.9, 0.2, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "arms", "TYPE": "float", "MIN": 1.0, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "twist", "TYPE": "float", "MIN": 0.5, "MAX": 3.0, "DEFAULT": 1.4 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  // 100 * 0.3 is whole, so the turn never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0);
  float s;
  if (isLine) {
    // A line can't spiral, so the bands run in from both ends towards the middle instead.
    s = fract(abs(uv.x - 0.5) * 2.0 * arms + t * 0.3);
  } else {
    float r = length(p);
    float a = atan(p.y, p.x) / 6.2831853;
    // Angle plus log-radius is a spiral; adding time turns it and draws it inward.
    s = fract(a * arms + log(r + 0.03) * twist + t * 0.3);
  }
  float aa = (isLine ? 4.0 : 2.0) * arms / max(RENDERSIZE.x, 8.0);
  float band = smoothstep(0.5 + aa, 0.5 - aa, abs(s - 0.5) * 2.0);
  // The dark half of each arm is not black: a dim version of the other colour keeps the whole
  // tunnel readable while the bright arm carries the spin.
  vec3 col = mix(colorB.rgb * 0.22, colorA.rgb, band);
  // The centre glows, which is what makes it a tunnel rather than a pinwheel.
  float centre = isLine ? 0.0 : smoothstep(0.22, 0.0, length(p));
  col = mix(col, colorB.rgb, centre);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Bright rays bursting outward from the centre and fading, one burst after another",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.8, 0.2, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "rays", "TYPE": "float", "MIN": 4.0, "MAX": 16.0, "DEFAULT": 8.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  // 100 * 0.25 is whole, so a burst never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0) + 1.2;
  float d = isLine ? abs(uv.x - 0.5) * 2.0 : length(p) / 0.72;
  float a = atan(p.y, p.x);
  // Rays: dark between them on a matrix; a line has no "between".
  float rayMask = isLine ? 1.0 : pow(abs(sin(a * rays * 0.5)), 1.8);
  // Two bursts half a cycle apart, so one is always on screen while the other is being born.
  float burst = 0.0;
  for (int i = 0; i < 2; i++) {
    float front = fract(t * 0.25 + float(i) * 0.5);
    float wave = smoothstep(front + 0.03, front - 0.03, d) * smoothstep(front - 0.4, front, d);
    burst = max(burst, wave);
  }
  // A constant hot centre, where every burst comes from.
  float core = smoothstep(0.28, 0.0, d);
  // The rays are faintly present all the time; the bursts light them up.
  vec3 col = colorA.rgb * (0.1 + 0.9 * burst) * rayMask;
  col = mix(col, colorB.rgb, core);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A sunrise climbing slowly, deep orange at the horizon fading up into brighter sky",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.35, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.9, 0.3, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.2, 0.5, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // 100 * 0.1 is whole: the sun climbs and resets every ten seconds at speed 1, seamlessly
  // because it rises through the bottom again rather than jumping.
  float phase = fract(mod(TIME * speed, 100.0) * 0.1);
  // The sun: a disc that rises from below the horizon to the upper third and back.
  float sunY = -0.2 + 0.9 * (0.5 - 0.5 * cos(phase * 6.2831853));
  vec2 p = isLine ? vec2(uv.x - 0.5, 0.0) : vec2((uv.x - 0.5) * aspect, uv.y - sunY);
  float sun = isLine ? smoothstep(0.35, 0.05, abs(uv.x - 0.5) / (0.3 + sunY)) : smoothstep(0.22, 0.14, length(p));
  // Sky: three flat bands - horizon glow, gold, then blue - that follow the sun up.
  float y = isLine ? 0.25 + 0.4 * sunY : uv.y;
  float band1 = smoothstep(sunY + 0.05, sunY + 0.2, y);
  float band2 = smoothstep(sunY + 0.35, sunY + 0.5, y);
  vec3 col = mix(colorA.rgb, colorB.rgb, band1);
  col = mix(col, colorC.rgb, band2);
  // Always well lit: even the highest sky is at half, and the horizon glows at full.
  float lit = 0.55 + 0.45 * (1.0 - band2 * 0.6);
  col *= lit;
  col = mix(col, colorB.rgb, sun);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A field of stars twinkling softly at different times over a deep coloured background",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.05, 0.15, 0.7, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.45 },
    { "NAME": "background", "TYPE": "float", "MIN": 0.1, "MAX": 0.8, "DEFAULT": 0.4 }
  ]
}*/
float hash(vec2 c) {
  return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}
void main() {
  vec2 uv = isf_FragNormCoord;
  // Every pixel is its own star: the point of a twinkle is that neighbours differ.
  vec2 cell = floor(uv * RENDERSIZE);
  float t = mod(TIME * speed, 62.831853);
  float h = hash(cell);
  float h2 = hash(cell + 19.0);
  float h3 = hash(cell + 41.0);
  // Only some pixels are stars, and each has its own phase and its own rate (0.8, 1.0 or 1.2,
  // all tenths so the wrap at 20 pi is seamless). The phase comes from its own hash: taking
  // it from the one that chose the star would give every star a phase in the same half-turn,
  // and they would all blink together.
  float isStar = step(1.0 - density, h);
  float rate = 0.8 + 0.2 * floor(h3 * 3.0);
  float pulse = 0.5 + 0.5 * sin(t * rate + h2 * 6.2831853);
  // Sharpened, so a star is mostly off and then bright rather than a slow uniform shimmer.
  float star = isStar * pow(pulse, 4.0);
  vec3 col = colorB.rgb * background;
  col = mix(col, colorA.rgb, star);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A row of VU meter bars bouncing up and down at different heights",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 1.0, 0.2, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.1, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "bars", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 8.0 }
  ]
}*/
float hash(float n) {
  return fract(sin(n * 91.7) * 43758.5453);
}
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float t = mod(TIME * speed, 62.831853);
  float level;
  float along;
  float seam = 1.0;
  if (isLine) {
    // A line is one bar, filling from the left.
    level = 0.45 + 0.45 * (0.5 + 0.5 * sin(t * 2.1)) * (0.5 + 0.5 * sin(t * 0.7 + 1.0));
    along = uv.x;
  } else {
    // Never narrower than three pixels a bar, or a seam would swallow the bar itself.
    float n = min(bars, max(1.0, floor(RENDERSIZE.x / 3.0)));
    float bar = floor(uv.x * n);
    float h = hash(bar);
    // Each bar bounces at its own pair of rates, all whole tenths so the wrap is seamless.
    float rate = 1.5 + 0.5 * floor(h * 4.0);
    float bounce = 0.5 + 0.5 * sin(t * rate + h * 6.28);
    float slow = 0.6 + 0.4 * sin(t * 0.3 + h * 3.0);
    level = 0.25 + 0.7 * bounce * slow;
    along = uv.y;
    // A dark seam between bars, so they read as bars.
    float fx = fract(uv.x * n);
    float aa = min(0.3, 1.2 * n / max(RENDERSIZE.x, 8.0));
    seam = smoothstep(0.0, aa, fx) * smoothstep(1.0, 1.0 - aa, fx);
  }
  float lit = step(along, level);
  // Green below, gold through the middle, red at the top: flat zones, like the real meter.
  vec3 col = colorA.rgb;
  col = mix(col, colorB.rgb, step(0.5, along));
  col = mix(col, colorC.rgb, step(0.8, along));
  // The unlit part of a bar is a dim ghost, so the meter's full scale is always visible.
  gl_FragColor = vec4(col * (0.12 + 0.88 * lit) * seam, 1.0);
}

